    write('scripts/check_increment16.py', '#!/usr/bin/env python3\n"""Run the frozen Increment 16 validator with successor-safe roadmap handling.\n\nThe historical Increment 16 contract is retained verbatim in\n``check_increment16_frozen.py``. Revision 1.20 and the unchecked Increment 17\nentry are the completed Increment 16 baseline, not permanent exact repository\nstate.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nfrom pathlib import Path\n\nimport check_increment16_frozen as frozen\n\nROOT = frozen.ROOT\nProblem = frozen.Problem\n\nSUCCESSOR_CONTRACT_ANCHORS = (\n    "- [x] **Increment 17 — ",\n    "roadmap does not retain one Increment 17 origin graph",\n)\n\n\ndef roadmap_revision(root: Path) -> tuple[int, ...]:\n    roadmap = root / "docs/roadmap/nodal-development-todo.md"\n    try:\n        lines = roadmap.read_text(encoding="utf-8").splitlines()\n    except OSError:\n        return ()\n    revisions = [\n        line.removeprefix("**Revision:** ")\n        for line in lines\n        if line.startswith("**Revision:** ")\n    ]\n    if len(revisions) != 1:\n        return ()\n    try:\n        return tuple(int(part) for part in revisions[0].split("."))\n    except ValueError:\n        return ()\n\n\ndef validate_files(root: Path = ROOT) -> list[Problem]:\n    root = root.resolve()\n    problems = frozen.validate_files(root)\n    roadmap_path = root / "docs/roadmap/nodal-development-todo.md"\n    try:\n        roadmap = roadmap_path.read_text(encoding="utf-8")\n    except OSError:\n        roadmap = ""\n    increment17 = [\n        line\n        for line in roadmap.splitlines()\n        if line.startswith("- [") and "**Increment 17 — " in line\n    ]\n    if roadmap_revision(root) >= (1, 20) and len(increment17) == 1:\n        problems = [\n            problem\n            for problem in problems\n            if problem.code not in {"NODAL-INC16-032", "NODAL-INC16-035"}\n        ]\n    return problems\n\n\ndef run_compile(root: Path, problems: list[Problem]) -> None:\n    frozen.run_compile(root, problems)\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--compile", action="store_true")\n    args = parser.parse_args()\n    problems = validate_files(ROOT)\n    if args.compile and not problems:\n        run_compile(ROOT, problems)\n    if problems:\n        for problem in problems:\n            print(f"{problem.code}: {problem.message}")\n        print(f"Increment 16 check failed with {len(problems)} problem(s)")\n        return 1\n    print("Increment 16 check passed")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n')
    write('scripts/check_increment17.py', '#!/usr/bin/env python3\n"""Validate Increment 17 source-span, semantic-naming, and origin-graph contracts."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nimport re\nimport subprocess\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\n\n@dataclass(frozen=True)\nclass Problem:\n    code: str\n    message: str\n\n\ndef text(root: Path, path: str, problems: list[Problem], code: str) -> str:\n    try:\n        return (root / path).read_text(encoding="utf-8")\n    except OSError as error:\n        problems.append(Problem(code, f"cannot read {path}: {error}"))\n        return ""\n\n\ndef object_json(\n    root: Path,\n    path: str,\n    problems: list[Problem],\n    code: str,\n) -> dict[str, object]:\n    try:\n        value = json.loads((root / path).read_text(encoding="utf-8"))\n    except (OSError, json.JSONDecodeError) as error:\n        problems.append(Problem(code, f"cannot load {path}: {error}"))\n        return {}\n    if not isinstance(value, dict):\n        problems.append(Problem(code, f"{path} is not a JSON object"))\n        return {}\n    return value\n\n\ndef require(\n    source: str,\n    fragments: tuple[str, ...],\n    problems: list[Problem],\n    code: str,\n    label: str,\n) -> None:\n    missing = [fragment for fragment in fragments if fragment not in source]\n    if missing:\n        problems.append(Problem(code, f"{label} lacks: {\', \'.join(missing)}"))\n\n\ndef roadmap_revision(roadmap: str) -> tuple[int, ...]:\n    revisions = [\n        line.removeprefix("**Revision:** ")\n        for line in roadmap.splitlines()\n        if line.startswith("**Revision:** ")\n    ]\n    if len(revisions) != 1:\n        return ()\n    try:\n        return tuple(int(part) for part in revisions[0].split("."))\n    except ValueError:\n        return ()\n\n\ndef validate_files(root: Path = ROOT) -> list[Problem]:\n    problems: list[Problem] = []\n    kernel = text(\n        root,\n        "core/scala/api/src/nodal/ElaborationConstructionKernel.scala",\n        problems,\n        "NODAL-INC17-001",\n    )\n    semantic = text(\n        root,\n        "core/scala/api/src/nodal/SemanticOriginKernel.scala",\n        problems,\n        "NODAL-INC17-002",\n    )\n    compiler = text(\n        root,\n        "core/scala/api/src/nodal/CompilerApi.scala",\n        problems,\n        "NODAL-INC17-003",\n    )\n    construction_tests = text(\n        root,\n        "core/scala/testkit/test/src/nodal/ConstructionKernelTests.scala",\n        problems,\n        "NODAL-INC17-004",\n    )\n    tests = text(\n        root,\n        "core/scala/testkit/test/src/nodal/SemanticOriginTests.scala",\n        problems,\n        "NODAL-INC17-005",\n    )\n    documentation = text(\n        root,\n        "docs/implementation/increment17-source-origin-naming.md",\n        problems,\n        "NODAL-INC17-006",\n    )\n    gate = text(\n        root,\n        "docs/design-gates/NodalSemanticOriginNaming-DG-v1.0.md",\n        problems,\n        "NODAL-INC17-007",\n    )\n    roadmap = text(\n        root,\n        "docs/roadmap/nodal-development-todo.md",\n        problems,\n        "NODAL-INC17-008",\n    )\n    predecessor = text(\n        root,\n        "scripts/check_increment16.py",\n        problems,\n        "NODAL-INC17-009",\n    )\n    frozen_predecessor = text(\n        root,\n        "scripts/check_increment16_frozen.py",\n        problems,\n        "NODAL-INC17-010",\n    )\n    command = text(root, "scripts/nodal.py", problems, "NODAL-INC17-011")\n    workflow = text(\n        root,\n        ".github/workflows/increment-17-source-origin-naming.yml",\n        problems,\n        "NODAL-INC17-012",\n    )\n    manifest = object_json(\n        root,\n        "tests/api/fixtures/increment17/manifest.json",\n        problems,\n        "NODAL-INC17-013",\n    )\n    public_manifest = object_json(\n        root,\n        "core/scala/api/public-api-v0.3.json",\n        problems,\n        "NODAL-INC17-014",\n    )\n\n    require(\n        kernel,\n        (\n            "SemanticOriginBuilder",\n            "semanticOrigin.captureModule",\n            "semanticOrigin.captureDomain",\n            "semanticOrigin.captureDeclaration",\n            "semanticOrigin.captureExpression",\n            "semanticOrigin.captureInstance",\n            "semanticOrigin.captureOperation",\n            "semanticOrigin.resolve()",\n            "semantic.sourceMap",\n            "private def expressionPath",\n            "private def domainPath",\n        ),\n        problems,\n        "NODAL-INC17-015",\n        "construction-kernel integration",\n    )\n    require(\n        semantic,\n        (\n            "java.lang.StackWalker",\n            "KernelNameSnapshot",\n            "KernelOriginSnapshot",\n            "KernelGeneratedNameSnapshot",\n            "SemanticOriginResult",\n            "discoverMemberNames",\n            "bindingNear",\n            "sink-affinity",\n            "shaped-view",\n            "stableDigest",\n            "SourceMapEntry",\n            "inlined = true",\n            \'"clock-port"\',\n            \'"reset-port"\',\n            \'"synchronizer"\',\n            \'"fifo"\',\n            \'"reset-controller"\',\n            \'"crossing"\',\n            \'"pipeline-state"\',\n            \'"fsm-state"\',\n            \'"anonymous-register"\',\n            \'"temporary"\',\n        ),\n        problems,\n        "NODAL-INC17-016",\n        "semantic-origin implementation",\n    )\n    for forbidden in (\n        "new ThreadLocal",\n        "DynamicVariable",\n        "System.identityHashCode",\n        ".hashCode()",\n        \'s"expr_${\',\n        \'s"${declaration.kind.label}_${reference.index}"\',\n    ):\n        if forbidden in semantic:\n            problems.append(\n                Problem("NODAL-INC17-017", f"prohibited semantic naming mechanism: {forbidden}")\n            )\n\n    require(\n        compiler,\n        (\n            "final case class SourceSpan(",\n            "final case class SourceMapEntry(",\n            "sourceMap: Vector[SourceMapEntry]",\n        ),\n        problems,\n        "NODAL-INC17-018",\n        "frozen compiler report surface",\n    )\n    require(\n        construction_tests,\n        (\n            \'Vector("KernelTop", "KernelTop.leaf")\',\n            \'find(_.name == "shaped")\',\n            "assert(emission.report.sourceMap.nonEmpty)",\n        ),\n        problems,\n        "NODAL-INC17-019",\n        "updated construction tests",\n    )\n    require(\n        tests,\n        (\n            "semantic names replace traversal-counter-only names",\n            "expression source maps survive inlined origins",\n            "generated infrastructure names cover required categories",\n            "origin graph records parents and sink affinity",\n            "SemanticOriginTop.child",\n            "pixel_sum",\n        ),\n        problems,\n        "NODAL-INC17-020",\n        "semantic-origin Scala tests",\n    )\n    require(\n        documentation,\n        (\n            "source binding",\n            "sink affinity",\n            "Traversal ordinals are never emitted as a normal name",\n            "expression-level source-map entries remain present",\n            "Public API v0.3 remains unchanged",\n        ),\n        problems,\n        "NODAL-INC17-021",\n        "implementation documentation",\n    )\n    require(\n        gate,\n        (\n            "**Status:** Approved",\n            "**Scope:** public-api",\n            "**Public API:** unchanged at 0.3",\n            "No traversal-counter-only normal names",\n            "source spans and origin edges",\n        ),\n        problems,\n        "NODAL-INC17-022",\n        "design gate",\n    )\n    require(\n        predecessor,\n        (\n            "- [x] **Increment 17 — ",\n            "roadmap does not retain one Increment 17 origin graph",\n            "check_increment16_frozen",\n        ),\n        problems,\n        "NODAL-INC17-023",\n        "Increment 16 successor adapter",\n    )\n    require(\n        frozen_predecessor,\n        (\n            "Validate Increment 16 construction-kernel contracts",\n            "NODAL-INC16-035",\n        ),\n        problems,\n        "NODAL-INC17-024",\n        "frozen Increment 16 checker",\n    )\n    require(\n        command,\n        (\n            \'_python(root, "check_increment16.py")\',\n            \'_python(root, "check_increment17.py")\',\n        ),\n        problems,\n        "NODAL-INC17-025",\n        "developer command integration",\n    )\n    require(\n        workflow,\n        (\n            "Increment 17 Source Origin Naming",\n            "permissions:\\n  contents: read",\n            "python3 scripts/check_increment17.py --compile",\n            "python3 tests/api/test_increment17.py",\n        ),\n        problems,\n        "NODAL-INC17-026",\n        "permanent workflow",\n    )\n\n    if public_manifest.get("api_version") != "0.3" or public_manifest.get("status") != "frozen":\n        problems.append(Problem("NODAL-INC17-027", "public API v0.3 identity changed"))\n    if manifest.get("increment") != 17 or manifest.get("public_api_changed") is not False:\n        problems.append(Problem("NODAL-INC17-028", "Increment 17 manifest identity is invalid"))\n    expected_contract = {\n        "scala_declaration_names": True,\n        "expression_spans": True,\n        "stable_origin_graph": True,\n        "sink_affinity": True,\n        "counter_only_normal_names": False,\n        "inlined_expression_source_maps": True,\n        "mutable_global_state": False,\n        "thread_local_state": False,\n        "jvm_identity_in_output": False,\n    }\n    if manifest.get("semantic_identity_contract") != expected_contract:\n        problems.append(Problem("NODAL-INC17-029", "semantic identity contract changed"))\n\n    unchecked = "- [ ] **Increment 17 — Source spans, semantic naming, and origin graph**"\n    checked = unchecked.replace("[ ]", "[x]", 1)\n    status = manifest.get("status")\n    validation = manifest.get("validation")\n    revision = roadmap_revision(roadmap)\n    if status == "preflight-origin-graph":\n        if validation != {\n            "pull_request": None,\n            "dedicated_workflow_run": None,\n            "core_ci_run": None,\n        }:\n            problems.append(Problem("NODAL-INC17-030", "preflight evidence is malformed"))\n        if unchecked not in roadmap or revision != (1, 20):\n            problems.append(Problem("NODAL-INC17-031", "preflight roadmap state is invalid"))\n    elif status == "validated-origin-graph":\n        if not isinstance(validation, dict) or not all(\n            isinstance(validation.get(key), int)\n            for key in ("pull_request", "dedicated_workflow_run", "core_ci_run")\n        ):\n            problems.append(Problem("NODAL-INC17-032", "final evidence is incomplete"))\n        if checked not in roadmap or revision != (1, 21):\n            problems.append(Problem("NODAL-INC17-033", "final roadmap state is invalid"))\n        if isinstance(validation, dict):\n            values = tuple(\n                validation.get(key)\n                for key in ("pull_request", "dedicated_workflow_run", "core_ci_run")\n            )\n            if (\n                f"PR [#{values[0]}]" not in roadmap\n                or f"[{values[1]}]" not in roadmap\n                or f"[{values[2]}]" not in roadmap\n            ):\n                problems.append(Problem("NODAL-INC17-034", "roadmap lacks final evidence"))\n    else:\n        problems.append(Problem("NODAL-INC17-035", f"unknown status: {status!r}"))\n\n    if "- [ ] **Increment 18 — Nodal MLIR dialect skeleton**" not in roadmap:\n        problems.append(Problem("NODAL-INC17-036", "Increment 18 is not left unchecked"))\n    if len(re.findall(r"^- \\[[ x]\\] \\*\\*Increment 17 — ", roadmap, re.MULTILINE)) != 1:\n        problems.append(\n            Problem("NODAL-INC17-037", "roadmap does not retain one Increment 17 origin graph")\n        )\n    return problems\n\n\ndef execute(root: Path, command: list[str]) -> subprocess.CompletedProcess[str]:\n    return subprocess.run(\n        command,\n        cwd=root,\n        check=False,\n        text=True,\n        stdout=subprocess.PIPE,\n        stderr=subprocess.STDOUT,\n        env={**os.environ, "NO_COLOR": "1"},\n    )\n\n\ndef run_compile(root: Path, problems: list[Problem]) -> None:\n    mill = root / ("mill.bat" if os.name == "nt" else "mill")\n    for index, arguments in enumerate(\n        (\n            ["mill.scalalib.scalafmt/checkFormatAll"],\n            ["scalafix.check"],\n            ["core.scala.testkit.test"],\n        ),\n        start=1,\n    ):\n        result = execute(root, [str(mill), *arguments])\n        if result.returncode != 0:\n            problems.append(\n                Problem(\n                    f"NODAL-INC17-{37 + index:03d}",\n                    f"command failed: {\' \'.join(arguments)}\\n{result.stdout}",\n                )\n            )\n            return\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--compile", action="store_true")\n    args = parser.parse_args()\n    problems = validate_files(ROOT)\n    if args.compile and not problems:\n        run_compile(ROOT, problems)\n    if problems:\n        for problem in problems:\n            print(f"{problem.code}: {problem.message}")\n        print(f"Increment 17 check failed with {len(problems)} problem(s)")\n        return 1\n    print("Increment 17 check passed")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n')
    write('tests/api/test_increment17.py', '#!/usr/bin/env python3\n"""Unit coverage for the Increment 17 repository contract checker."""\n\nfrom __future__ import annotations\n\nimport importlib.util\nimport sys\nimport unittest\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[2]\nCHECKER = ROOT / "scripts/check_increment17.py"\nSPEC = importlib.util.spec_from_file_location("check_increment17", CHECKER)\nassert SPEC is not None and SPEC.loader is not None\nMODULE = importlib.util.module_from_spec(SPEC)\nsys.modules[SPEC.name] = MODULE\nSPEC.loader.exec_module(MODULE)\n\n\nclass Increment17ContractTests(unittest.TestCase):\n    def test_repository_contract(self) -> None:\n        problems = MODULE.validate_files(ROOT)\n        self.assertEqual([], problems, "\\n".join(f"{p.code}: {p.message}" for p in problems))\n\n\nif __name__ == "__main__":\n    unittest.main()\n')
    write('tests/api/fixtures/increment17/manifest.json', '{\n  "schema": 1,\n  "increment": 17,\n  "status": "preflight-origin-graph",\n  "public_api_changed": false,\n  "public_api_version": "0.3",\n  "semantic_identity_contract": {\n    "scala_declaration_names": true,\n    "expression_spans": true,\n    "stable_origin_graph": true,\n    "sink_affinity": true,\n    "counter_only_normal_names": false,\n    "inlined_expression_source_maps": true,\n    "mutable_global_state": false,\n    "thread_local_state": false,\n    "jvm_identity_in_output": false\n  },\n  "generated_name_categories": [\n    "clock-port",\n    "reset-port",\n    "synchronizer",\n    "fifo",\n    "reset-controller",\n    "crossing",\n    "pipeline-state",\n    "fsm-state",\n    "anonymous-register",\n    "temporary"\n  ],\n  "validation": {\n    "pull_request": null,\n    "dedicated_workflow_run": null,\n    "core_ci_run": null\n  }\n}\n')
    write('docs/design-gates/NodalSemanticOriginNaming-DG-v1.0.md', '# Nodal semantic origin and naming design gate v1.0\n\n**Revision:** v1.0\n**Status:** Approved\n**Scope:** public-api\n**Public API:** unchanged at 0.3\n**Approved authority:** standing Nodal increment implementation and merge authorization\n\n## Decision\n\nImplement source-span capture, semantic naming, source binding, sink affinity, and a stable private\norigin graph beneath the frozen public API. Populate the already-frozen `DesignReport.sourceMap` without\nadding user-visible syntax.\n\n## Required contracts\n\n- Capture repository-relative Scala source spans and nearby declaration bindings transactionally.\n- Discover class members only in a lexicographically sorted order; JVM reflection order is not identity.\n- Prefer explicit names, Scala declarations, shaped-view derivation, and sink affinity before a\n  source-derived digest.\n- No traversal-counter-only normal names are permitted.\n- Retain expression-level source maps for nodes that may be inlined.\n- Record deterministic names for modules, declarations, shaped views, domains, generated clock/reset\n  ports, synchronizers, FIFOs, reset controllers, crossings, pipeline/FSM state, anonymous registers,\n  and required temporaries.\n- Record source spans and origin edges without mutable global state, thread-local state, identity hashes,\n  allocation addresses, or backend-specific naming.\n- Preserve public API v0.3, the core/library boundary, and the transactional construction lifecycle.\n\n## Deferred work\n\nMLIR lowering, backend materialization decisions, generated infrastructure emission, scheduling,\nverification passes, and HDL output remain deferred to later roadmap increments.\n')
    write('docs/implementation/increment17-source-origin-naming.md', '# Increment 17 source spans, semantic naming, and origin graph\n\n## Status\n\nIncrement 17 implements semantic identity and source provenance beneath the frozen Nodal public API v0.3.\nPublic API v0.3 remains unchanged. The implementation enriches private construction snapshots and the\nalready-frozen `DesignReport.sourceMap`; it does not add source syntax or backend-visible classes.\n\n## Source capture\n\nEvery module, domain, declaration, expression, instance, and construction operation captures a\ntransaction-local source site with `StackWalker`. Internal API frames are separated from the first user\nScala frame, so the record retains both the public operation that created the node and the user source\nspan that requested it.\n\nThe source locator resolves repository-relative paths and line/column ranges without storing absolute\ncheckout paths. It also reads the nearby Scala source binding when a construction call appears in a\n`val`, `var`, or `lazy val`. This source binding complements lexicographically sorted member reflection:\nmember reflection finds stable class fields, while source binding captures constructor-local\ndeclarations such as a register or child instance inside a lexical domain block.\n\nAll source lookup caches are owned by one construction transaction. No mutable global, thread-local, or\nJVM identity value enters a stable result.\n\n## Semantic naming\n\nNormal names are selected in this order:\n\n1. an explicit Nodal name such as `.named("pixel_sum")` or an endpoint name;\n2. a captured Scala source binding or class member;\n3. a shaped-view name derived from its source value and operation;\n4. a sink-affinity name derived from a named assignment or connection target;\n5. an operation/source-span stem plus a stable SHA-256 digest.\n\nCollisions are resolved with a digest of semantic source material. Traversal ordinals are never emitted\nas a normal name. An ordinal may participate only in the digest used to disambiguate two otherwise\nidentical source sites, so a name never degrades to `wire_3`, `expr_17`, or an equivalent counter-only\nform.\n\nModule paths use the Scala instance binding (`Top.child`) rather than a child class plus instance\ncounter. Declarations, domains, shaped elements/views, and expressions share a deterministic module\nnamespace. Generated names are recorded separately for clock/reset ports, synchronizers, FIFOs, reset\ncontrollers, crossings, pipeline/FSM state, anonymous registers, and required temporaries.\n\n## Origin and sink affinity\n\nThe private origin graph assigns every captured module, instance, domain, declaration, and expression a\nstable origin ID. Each node records:\n\n- its semantic path and construction operation;\n- its repository-relative source span;\n- parent semantic paths derived from operands or hierarchy;\n- an optional assignment/connection sink;\n- whether an expression may be inlined.\n\nThe graph is deterministic across repeated and parallel elaborations. Runtime object identity is used\nonly to join live Scala objects while the transaction is open; emitted paths, IDs, and digests contain no\nidentity hash, allocation address, reflection order, or mutable-global sequence.\n\n## Source-map retention\n\n`ConstructionSnapshot.sourceMap` and `DesignReport.sourceMap` now contain the sorted semantic-path to\n`SourceSpan` mapping. Every captured expression receives an entry. Expressions marked as inlined retain\ntheir original expression-level source-map entries, rather than inheriting only the eventual sink\nlocation.\n\n## Deliberate boundaries\n\nIncrement 17 does not lower the origin graph to MLIR or HDL, choose backend materialization policy,\nschedule pipeline stages, or emit generated clock/reset and crossing structures. The generated-name\ninventory is deterministic metadata for those later passes. Increment 18 begins the Nodal MLIR dialect\nskeleton.\n')
    write('.github/workflows/increment-17-source-origin-naming.yml', 'name: Increment 17 Source Origin Naming\n\non:\n  pull_request:\n    branches:\n      - dev\n\npermissions:\n  contents: read\n\njobs:\n  source-origin-naming:\n    name: increment-17/source-origin-naming\n    runs-on: ubuntu-24.04\n    timeout-minutes: 75\n\n    steps:\n      - name: Check out repository\n        uses: actions/checkout@v6\n        with:\n          fetch-depth: 0\n\n      - name: Bootstrap pinned contract toolchain\n        run: |\n          ./nodal style bootstrap --prefix "${RUNNER_TEMP}/nodal-lint-toolchain"\n          echo "NODAL_LINT_TOOLCHAIN=${RUNNER_TEMP}/nodal-lint-toolchain" >> "$GITHUB_ENV"\n\n      - name: Validate semantic origin and predecessor contracts\n        run: |\n          ./mill mill.scalalib.scalafmt/checkFormatAll\n          ./mill scalafix.check\n          python3 scripts/check_increment15.py --compile-negative\n          python3 scripts/check_increment16.py\n          python3 scripts/check_increment17.py --compile\n          python3 tests/api/test_increment16.py\n          python3 tests/api/test_increment17.py\n          python3 scripts/check_formatting_baseline.py\n          python3 scripts/check_markdown.py\n          python3 scripts/check_package_visibility.py\n          ./nodal check \\\n            --contracts-only \\\n            --online-toolchain \\\n            --lint-toolchain "${NODAL_LINT_TOOLCHAIN}" \\\n            --base-ref origin/dev\n          git diff --check\n')
    replace_once('scripts/nodal.py', '        _python(root, "check_increment16.py"),\n', '        _python(root, "check_increment16.py"),\n        _python(root, "check_increment17.py"),\n')
    append_once('.github/CODEOWNERS', '/scripts/check_increment17.py @pysolvesemi', '# Increment 17 semantic identity, provenance, and regression closure.\n/core/scala/api/src/nodal/SemanticOriginKernel.scala @pysolvesemi\n/scripts/check_increment16_frozen.py @pysolvesemi\n/scripts/check_increment17.py @pysolvesemi\n/tests/api/test_increment17.py @pysolvesemi\n/tests/api/fixtures/increment17/manifest.json @pysolvesemi\n/.github/workflows/increment-17-source-origin-naming.yml @pysolvesemi\n/core/scala/testkit/test/src/nodal/SemanticOriginTests.scala @pysolvesemi\n/docs/design-gates/NodalSemanticOriginNaming-DG-v1.0.md @pysolvesemi\n/docs/implementation/increment17-source-origin-naming.md @pysolvesemi\n')
    (ROOT / '.github/workflows/increment-17-materialize.yml').unlink(missing_ok=True)
